import { test, expect } from '@playwright/test';

test.describe('Internet Connection Drop Friendly Message', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should display friendly message when internet connection drops', async ({ page }) => {
    // Verify initial page loads successfully
    const welcomeMessage = page.getByRole('heading', { name: /welcome/i });
    await expect(welcomeMessage).toBeVisible();

    // Simulate internet connection drop
    await page.route('**/api/data', route => {
      route.abort('failed');
    });

    // Trigger data fetch
    const refreshButton = page.getByRole('button', { name: /refresh/i });
    await refreshButton.click();

    // Wait for error state to render
    await page.waitForTimeout(500);

    // Verify friendly error message is displayed
    const errorMessage = page.getByText(/internet connection lost/i);
    await expect(errorMessage).toBeVisible();

    // Verify connection status indicator shows error
    const statusIndicator = page.getByLabel(/connection status/i);
    await expect(statusIndicator).toContainText('offline');

    // Verify user can retry connection
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();
    await expect(retryButton).not.toBeDisabled();
  });

  test('should hide friendly message when internet connection is restored', async ({ page }) => {
    // Verify initial page loads successfully
    const welcomeMessage = page.getByRole('heading', { name: /welcome/i });
    await expect(welcomeMessage).toBeVisible();

    // Simulate internet connection drop
    await page.route('**/api/data', route => {
      route.abort('failed');
    });

    // Trigger data fetch to simulate connection loss
    const refreshButton = page.getByRole('button', { name: /refresh/i });
    await refreshButton.click();

    // Wait for error state to render
    await page.waitForTimeout(500);

    // Verify friendly error message is displayed
    const errorMessage = page.getByText(/internet connection lost/i);
    await expect(errorMessage).toBeVisible();

    // Restore internet connection
    await page.route('**/api/data', route => {
      route.continue();
    });

    // Trigger data fetch again
    await refreshButton.click();

    // Wait for data to load
    await page.waitForTimeout(500);

    // Verify friendly error message is no longer visible
    await expect(errorMessage).not.toBeVisible();

    // Verify data is displayed
    const dataTable = page.getByRole('region', { name: /data table/i });
    await expect(dataTable).toBeVisible();

    // Verify connection status indicator shows online
    const statusIndicator = page.getByLabel(/connection status/i);
    await expect(statusIndicator).toContainText('online');
  });
});
